import os
import subprocess
import json
import requests

def main(image_url: str, text_overlay: str = "", tts_text: str = "", effect: str = "ken_burns"):
    # Download image
    img_path = "/tmp/video_input.jpg"
    os.makedirs("/tmp/video_gen_output", exist_ok=True)

    if image_url.startswith("http"):
        r = requests.get(image_url, timeout=30)
        with open(img_path, "wb") as f:
            f.write(r.content)
    else:
        img_path = image_url

    # Build command
    cmd = ["python3", "/home/openhands/erp-core/erp-core/dify-modules/video-gen/video_gen.py", "video", img_path]
    if text_overlay:
        cmd.extend(["-t", text_overlay])
    if tts_text:
        cmd.extend(["--tts", tts_text])
    cmd.extend(["--effect", effect, "--duration", "5", "-o", "/tmp/video_gen_output/output.mp4"])

    result = subprocess.run(cmd, capture_output=True, text=True, timeout=120)

    if result.returncode != 0:
        return {"error": result.stderr}

    return {
        "video_path": "/tmp/video_gen_output/output.mp4",
        "status": "success",
        "output": result.stdout
    }
